answer.sql:
SELECT SUM(pa.Policy_Amount) AS total_premium
FROM premium p
JOIN policy_amount pa ON p.Policy_Amount_Identifier = pa.Policy_Amount_Identifier;

SELECT AVG(DATE_DIFF('day', Claim_Open_Date, Claim_Close_Date)) AS avg_days_to_close
FROM claim
WHERE Claim_Open_Date IS NOT NULL AND Claim_Close_Date IS NOT NULL;

SELECT AVG(Loss_Ratio) AS average_loss_ratio
FROM fire_claim
WHERE Year_Built < 1970;

SELECT SUM(ca.Claim_Amount) AS total_loss_reserve
FROM claim_amount ca
JOIN loss_reserve lr ON ca.Claim_Amount_Identifier = lr.Claim_Amount_Identifier;

